"""Control-plane client. Performance traffic is generated by the Go binary."""
from __future__ import annotations
import json
import socket
import struct
import time
from typing import Any
MAX_FRAME = 8 * 1024 * 1024

def address_parts(address: str) -> tuple[str, int]:
    host, port = address.rsplit(":", 1)
    return host.strip("[]"), int(port)

def exact(sock: socket.socket, count: int) -> bytes:
    chunks = bytearray()
    while len(chunks) < count:
        data = sock.recv(count - len(chunks))
        if not data:
            raise ConnectionError("truncated frame")
        chunks.extend(data)
    return bytes(chunks)

def request(address: str, payload: dict[str, Any], timeout: float = 2.0) -> dict[str, Any]:
    encoded = json.dumps(payload, separators=(",", ":")).encode()
    if len(encoded) > MAX_FRAME:
        raise ValueError("request exceeds frame limit")
    with socket.create_connection(address_parts(address), timeout=timeout) as sock:
        sock.settimeout(timeout)
        sock.sendall(struct.pack(">I", len(encoded)) + encoded)
        length, = struct.unpack(">I", exact(sock, 4))
        if length > MAX_FRAME:
            raise ValueError("response exceeds frame limit")
        response = json.loads(exact(sock, length))
        if not isinstance(response, dict) or "status" not in response:
            raise ValueError("malformed response")
        return response

def statuses(nodes: dict[int, str]) -> dict[int, dict[str, Any]]:
    result = {}
    for node, address in nodes.items():
        try:
            result[node] = request(address, {"op": "status"}, timeout=.5)
        except (OSError, ValueError):
            continue
    return result

def complete_statuses(nodes: dict[int, str], timeout: float = 20.0) -> dict[int, dict[str, Any]]:
    """Wait for one status pass that identifies every configured node."""
    deadline = time.monotonic() + timeout
    observed: dict[int, dict[str, Any]] = {}
    while time.monotonic() < deadline:
        observed = statuses(nodes)
        if set(observed) == set(nodes) and all(
            response.get("status") == "ok"
            and response.get("info", {}).get("node_id") == node
            for node, response in observed.items()
        ):
            return observed
        time.sleep(.05)
    missing = sorted(
        node for node in nodes
        if node not in observed
        or observed[node].get("status") != "ok"
        or observed[node].get("info", {}).get("node_id") != node
    )
    raise TimeoutError(f"valid status observation did not include nodes {missing}")

def leader(nodes: dict[int, str], timeout: float = 20.0) -> int:
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline:
        candidates = [node for node, r in statuses(nodes).items()
                      if r.get("status") == "ok" and r.get("info", {}).get("leader")]
        if len(candidates) == 1:
            return candidates[0]
        time.sleep(.05)
    raise TimeoutError("no unique reported leader (a status observation is not a quorum proof)")

def execute(nodes: dict[int, str], command: dict[str, Any], timeout: float = 15) -> dict[str, Any]:
    deadline = time.monotonic() + timeout
    last: Any = None
    while time.monotonic() < deadline:
        for address in nodes.values():
            try:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    break
                last = request(address, {"op": "execute", "command": command}, min(1.0, remaining))
                if last.get("status") == "ok" and isinstance(last.get("result"), dict):
                    if last["result"].get("error"):
                        raise ValueError(last["result"]["error"])
                    return last["result"]
                if last.get("status") == "error":
                    raise ValueError(last.get("detail", "application error"))
            except OSError as exc:
                last = str(exc)
        time.sleep(.02)
    raise TimeoutError(f"operation outcome unknown after retries: {last}")
